import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"28、【大過】 巽下兌上","description":"橫渠易說 - 28、【大過】 巽下兌上","frontmatter":{"title":"28、【大過】 巽下兌上","description":"橫渠易說 - 28、【大過】 巽下兌上"},"headers":[],"relativePath":"classics/hengqu/030.md","filePath":"classics/hengqu/030.md"}'),l={name:"classics/hengqu/030.md"};function t(n,a,s,d,c,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_28、【大過】-巽下兌上" tabindex="-1">28、【大過】 巽下兌上 <a class="header-anchor" href="#_28、【大過】-巽下兌上" aria-label="Permalink to “28、【大過】 巽下兌上”">​</a></h1><h3 id="彖曰-大過-大者過也。-棟撓-本末弱也。剛過而中-巽而說行-利有攸往乃亨-大過之時大矣哉" tabindex="-1">彖曰：“大過”，大者過也。“棟撓”，本末弱也。剛過而中，巽而說行，利有攸往乃亨，大過之時大矣哉! <a class="header-anchor" href="#彖曰-大過-大者過也。-棟撓-本末弱也。剛過而中-巽而說行-利有攸往乃亨-大過之時大矣哉" aria-label="Permalink to “彖曰：“大過”，大者過也。“棟撓”，本末弱也。剛過而中，巽而說行，利有攸往乃亨，大過之時大矣哉!”">​</a></h3><h3 id="象曰-澤滅木-大過-君子以獨立不懼-遁世無悶。" tabindex="-1">象曰：澤滅木，大過，君子以獨立不懼，遁世無悶。 <a class="header-anchor" href="#象曰-澤滅木-大過-君子以獨立不懼-遁世無悶。" aria-label="Permalink to “象曰：澤滅木，大過，君子以獨立不懼，遁世無悶。”">​</a></h3><p>陽剛過實於中，本末過弱於外，故當過矯相與也。</p><h3 id="初六-藉用白茅-無咎。-象曰-藉用白茅-柔在下也。" tabindex="-1">初六，藉用白茅，無咎。 象曰：“藉用白茅”，柔在下也。 <a class="header-anchor" href="#初六-藉用白茅-無咎。-象曰-藉用白茅-柔在下也。" aria-label="Permalink to “初六，藉用白茅，無咎。 象曰：“藉用白茅”，柔在下也。”">​</a></h3><h3 id="九二-枯楊生稊-老夫得其女妻-無不利。-象曰-老夫女妻-過以相與也。" tabindex="-1">九二，枯楊生稊，老夫得其女妻，無不利。 象曰：老夫女妻，過以相與也。 <a class="header-anchor" href="#九二-枯楊生稊-老夫得其女妻-無不利。-象曰-老夫女妻-過以相與也。" aria-label="Permalink to “九二，枯楊生稊，老夫得其女妻，無不利。 象曰：老夫女妻，過以相與也。”">​</a></h3><p>扶衰於上，使枯木生稊，拯弱於下，使微陰獲助，此剛中下濟之功，亦自獲助於物也。</p><h3 id="九三-棟撓-兇。-象曰-棟撓之兇-不可以有輔也。" tabindex="-1">九三，棟撓，兇。 象曰：棟撓之兇，不可以有輔也。 <a class="header-anchor" href="#九三-棟撓-兇。-象曰-棟撓之兇-不可以有輔也。" aria-label="Permalink to “九三，棟撓，兇。 象曰：棟撓之兇，不可以有輔也。”">​</a></h3><h3 id="九四-棟隆-吉。有它吝。-象曰-棟隆之吉-不撓乎下也。" tabindex="-1">九四，棟隆，吉。有它吝。 象曰：棟隆之吉，不撓乎下也。 <a class="header-anchor" href="#九四-棟隆-吉。有它吝。-象曰-棟隆之吉-不撓乎下也。" aria-label="Permalink to “九四，棟隆，吉。有它吝。 象曰：棟隆之吉，不撓乎下也。”">​</a></h3><p>志在拯弱則棟隆而吉，若私應為心則撓乎下，吝也。</p><h3 id="九五-枯楊生華-老婦得其士夫-無咎無譽。-象曰-枯楊生華-何可久也-老婦士夫-亦可醜也。" tabindex="-1">九五，枯楊生華，老婦得其士夫，無咎無譽。 象曰：“枯楊生華”，何可久也!老婦士夫，亦可醜也。 <a class="header-anchor" href="#九五-枯楊生華-老婦得其士夫-無咎無譽。-象曰-枯楊生華-何可久也-老婦士夫-亦可醜也。" aria-label="Permalink to “九五，枯楊生華，老婦得其士夫，無咎無譽。 象曰：“枯楊生華”，何可久也!老婦士夫，亦可醜也。”">​</a></h3><p>九五上繫上六，故不能下濟大事，徒益其末耳，無拯物之心，所施者狹。老婦士夫，所與者不足道。枯楊生華，勢不能久，故無譽；未至長亂，故無咎。</p><h3 id="上六-過涉滅頂-兇-無咎。-象曰-過涉之兇-不可咎也。" tabindex="-1">上六，過涉滅頂，兇，無咎。 象曰：過涉之兇，不可咎也。 <a class="header-anchor" href="#上六-過涉滅頂-兇-無咎。-象曰-過涉之兇-不可咎也。" aria-label="Permalink to “上六，過涉滅頂，兇，無咎。 象曰：過涉之兇，不可咎也。”">​</a></h3><p>陰居上極，雖過而不足涉難，故兇。大過之極，故滅頂而無咎也。</p>',14)])])}const b=e(l,[["render",t]]);export{p as __pageData,b as default};
